261	  const persistSnapshot = useCallback(
262	    async (
263	      snapshot: Member,
264	      revision: number,
265	      opts?: { autosave?: boolean },
266	    ): Promise<boolean> => {
267	      const isCurrent = () => revision === latestSaveRevisionRef.current;
268	      const nextErrors: { firstName?: string; lastName?: string } = {};
269	      if (!snapshot.firstName.trim())
270	        nextErrors.firstName = t("error-firstname-required");
271	      if (!snapshot.lastName.trim())
272	        nextErrors.lastName = t("error-lastname-required");
273	      if (isCurrent()) setErrors(nextErrors);
274	      if (Object.keys(nextErrors).length > 0) {
275	        if (opts?.autosave && isCurrent()) {
276	          setSaveStatus("idle");
277	        } else if (!opts?.autosave && isCurrent()) {
278	          (nextErrors.firstName ? firstNameRef : lastNameRef).current?.focus();
279	        }
280	        return false;
281	      }
282	
283	      // Same-named people are only treated as duplicates once a birth date has
284	      // been entered; without one we allow namesakes to be created freely.
285	      const duplicate = snapshot.date.birth
286	        ? members.find(
287	            (m) =>
288	              m.id !== member.id &&
289	              m.firstName === snapshot.firstName &&
290	              (m.middleNames || "") === (snapshot.middleNames || "") &&
291	              (m.baptismalName || "") === (snapshot.baptismalName || "") &&
292	              m.lastName === snapshot.lastName &&
293	              m.gender === snapshot.gender &&
294	              m.date.birth === snapshot.date.birth &&
295	              m.date.death === snapshot.date.death,
296	          )
297	        : undefined;
298	
299	      if (duplicate) {
300	        const signature = [
301	          snapshot.firstName,
302	          snapshot.middleNames || "",
303	          snapshot.baptismalName || "",
304	          snapshot.lastName,
305	          snapshot.gender,
306	          snapshot.date.birth,
307	          snapshot.date.death || "",
308	        ].join("|");
309	        if (isCurrent() && lastDuplicateSignatureRef.current !== signature) {
310	          toast.error(t("toast-error-duplicate"));
311	          lastDuplicateSignatureRef.current = signature;
312	        }
313	        if (isCurrent()) setSaveStatus("error");
314	        return false;
315	      }
316	      if (isCurrent()) lastDuplicateSignatureRef.current = null;
317	
318	      if (isNew) {
319	        onSaved?.(snapshot);
320	        return true;
321	      }
322	
323	      setSaveStatus("saving");
324	      try {
325	        const treeId = editorTreeIdRef.current;
326	        if (!treeId) return false;
327	        const result = await updateMemberPartial(
328	          editorMemberIdRef.current,
329	          {
330	            academicTitle: snapshot.academicTitle || null,
331	            firstName: snapshot.firstName,
332	            middleNames: snapshot.middleNames || null,
333	            baptismalName: snapshot.baptismalName || null,
334	            lastName: snapshot.lastName,
335	            maidenName: snapshot.maidenName || null,
336	            gender: snapshot.gender,
337	            imageData: snapshot.imageData || undefined,
338	            dateOfBirth: snapshot.date.birth,
339	            dateOfDeath: snapshot.date.death || null,
340	            deceased: snapshot.deceased,
341	            adopted: snapshot.adopted,
342	            additionalData: snapshot.additionalData || null,
343	            birthplace: snapshot.birthplace || null,
344	            hometown: snapshot.hometown || null,
345	            cemetery: snapshot.cemetery || null,
346	            placesLived:
347	              snapshot.placesLived.length > 0
348	                ? JSON.stringify(snapshot.placesLived)
349	                : null,
350	            paternalParentId: snapshot.parents.paternalParent,
351	            maternalParentId: snapshot.parents.maternalParent,
352	            ...(snapshot.linkedTreeId !== undefined
353	              ? { linkedTreeId: snapshot.linkedTreeId }
354	              : {}),
355	          },
356	          treeId,
357	        );
358	        if (!opts?.autosave && isCurrent()) {
359	          toast.success(t("toast-success"));
360	        }
361	        // Bridge person whose counterpart tree the editor may not write: the
362	        // save worked but the linked copy drifted — say so.
363	        if (isCurrent() && result?.bridgeSync === "skipped_no_access") {
364	          toast.info(t("toast-bridge-sync-skipped"));
365	        }
366	        // Settle the dirty baseline on the snapshot that was actually
367	        // persisted — if the user kept typing during the in-flight save,
368	        // formData has since moved on and stays (correctly) dirty.
369	        // Serialization prevents reordered writes; this guard also prevents an
370	        // older response from replacing the status of a newer queued revision.
371	        if (isCurrent()) {
372	          setInitialData(snapshot);
373	          setSaveStatus("saved");
374	        }
375	        if (!opts?.autosave && isCurrent()) {
376	          onSaved?.(snapshot);
377	        }
378	        return true;
379	      } catch (err: unknown) {
380	        if (!isCurrent()) return false;
381	        if (err instanceof ApiError && err.status === 413) {
382	          const bucket = getQuotaBucket(err.message);
383	          if (bucket) {
384	            toast.error(t(quotaToastKey(bucket)));
385	          } else {
386	            toast.error(t("toast-error-image-too-large"));
387	          }
388	        } else if (err instanceof ApiError && err.status === 400) {
389	          toast.error(t("toast-error-image-unsupported"));
390	        } else {
391	          toast.error(t("toast-error-save"));
392	        }
393	        setSaveStatus("error");
394	        return false;
395	      }
396	    },
397	    [members, isNew, onSaved, t, updateMemberPartial],
398	  );
