843	                          onChange={(value) => {
844	                            const next = formData.placesLived.map((p, i) =>
845	                              i === idx ? { ...p, location: value } : p,
846	                            );
847	                            handleChange("placesLived", next);
848	                          }}
849	                          trailing={
850	                            <button
851	                              type="button"
852	                              className="text-muted-foreground hover:text-destructive transition-colors"
853	                              onClick={() => {
854	                                handleChange(
855	                                  "placesLived",
856	                                  formData.placesLived.filter(
857	                                    (_, i) => i !== idx,
858	                                  ),
859	                                );
860	                              }}
861	                            >
862	                              <Trash2 className="size-3.5" />
863	                            </button>
864	                          }
865	                        />
866	                        <div className="flex gap-1">
867	                          <Input
868	                            value={place.from || ""}
869	                            className="h-7 text-xs! shadow-none"
870	                            placeholder={t("places-lived-from")}
871	                            onChange={(e) => {
872	                              const next = formData.placesLived.map((p, i) =>
873	                                i === idx
874	                                  ? { ...p, from: e.target.value || null }
875	                                  : p,
876	                              );
877	                              handleChange("placesLived", next);
878	                            }}
879	                          />
880	                          <Input
881	                            value={place.to || ""}
882	                            className="h-7 text-xs! shadow-none"
883	                            placeholder={t("places-lived-to")}
884	                            onChange={(e) => {
885	                              const next = formData.placesLived.map((p, i) =>
886	                                i === idx
887	                                  ? { ...p, to: e.target.value || null }
888	                                  : p,
889	                              );
890	                              handleChange("placesLived", next);
891	                            }}
892	                          />
893	                        </div>
894	                      </div>
895	                    ))}
896	                    {formData.placesLived.length === 0 && (
897	                      <p className="text-xs text-muted-foreground">
898	                        {t("places-lived-empty")}
899	                      </p>
900	                    )}
901	                  </div>
902	                </Field>
903	              )}
904	
905	              {biographyEnabled && (
906	                <Field>
907	                  <FieldLabel className="text-[12px] font-semibold text-muted-foreground uppercase">
908	                    {t("notes-field")}
909	                  </FieldLabel>
910	                  <MarkdownEditor
911	                    id="additionalData"
912	                    value={formData.additionalData || ""}
913	                    placeholder={t("notes-placeholder")}
914	                    onChange={(value) => handleChange("additionalData", value)}
915	                  />
916	                </Field>
917	              )}
918	            </FieldGroup>
919	          </TabsContent>
920	
921	          {/* Relations tab */}
922	          {!isNew && (
923	            <TabsContent value="relations">
924	              <FieldGroup className="gap-4">
925	                <Field>
926	                  <FieldLabel className="text-[12px] font-semibold text-muted-foreground uppercase">
927	                    {t("paternal-parent-field")}
928	                  </FieldLabel>
929	                  <MemberPicker
930	                    members={eligibleParents}
931	                    value={formData.parents.paternalParent}
932	                    onChange={(id) =>
933	                      setFormData((prev) => ({
934	                        ...prev,
935	                        parents: { ...prev.parents, paternalParent: id },
936	                      }))
937	                    }
938	                    placeholder={t("parent-placeholder")}
939	                    noResultsText={t("parent-no-results")}
940	                  />
941	                </Field>
942	
943	                <Field>
944	                  <FieldLabel className="text-[12px] font-semibold text-muted-foreground uppercase">
945	                    {t("maternal-parent-field")}
946	                  </FieldLabel>
947	                  <MemberPicker
948	                    members={eligibleParents}
949	                    value={formData.parents.maternalParent}
950	                    onChange={(id) =>
951	                      setFormData((prev) => ({
952	                        ...prev,
953	                        parents: { ...prev.parents, maternalParent: id },
954	                      }))
955	                    }
956	                    placeholder={t("parent-placeholder")}
957	                    noResultsText={t("parent-no-results")}
958	                  />
959	                </Field>
960	
961	                {treeLinksEnabled && (
962	                  <LinkedTreeField
963	                    currentTreeId={currentTreeId}
964	                    value={formData.linkedTreeId ?? null}
965	                    memberName={`${formData.firstName} ${formData.lastName}`}
966	                    memberId={isNew ? undefined : formData.id}
967	                    formDirty={isDirty}
968	                    onChange={(treeId) => handleChange("linkedTreeId", treeId)}
969	                  />
970	                )}
971	              </FieldGroup>
972	            </TabsContent>
973	          )}
974	
975	          {/* Records tab — lazy-mounted on first activate */}
976	          {!isNew && (
977	            <TabsContent value="records">
978	              {recordsMounted && (
979	                <div className="space-y-4">
980	                  {galleryEnabled && <MemberPhotos member={member} />}
981	                  {eventsEnabled && <MemberEvents member={member} />}
982	                  {storiesEnabled && <MemberStories member={member} />}
983	                  {documentsEnabled && <MemberDocuments member={member} />}
984	                  {diseasesEnabled && <MemberDiseases member={member} />}
985	                  {tasksEnabled && <MemberTasks member={member} />}
986	                </div>
987	              )}
988	            </TabsContent>
989	          )}
990	        </Tabs>
991	      </div>
992	    </form>
993	  );
994	};
