9	import { Textarea } from "@/components/ui/textarea";
10	import { Button } from "@/components/ui/button";
11	import { GalleryImage, GalleryMemberLink } from "@/types/gallery";
12	import { useMemberStore } from "@/hooks/useMemberStore";
13	import { getMemberFullName } from "@/utils/memberUtils";
14	import { useGalleryStore } from "@/hooks/useGalleryStore";
15	import { PointerEvent, useEffect, useMemo, useRef, useState } from "react";
16	import { toast } from "sonner";
17	import { Field, FieldGroup, FieldLabel } from "@/components/ui/field";
18	import { PartialDatePicker } from "@/components/ui/partial-date-picker";
19	import { useTranslation } from "react-i18next";
20	import { MemberPicker } from "@/components/shared/member-sheet/MemberPicker";
21	import { useTreeStore } from "@/hooks/useTreeStore";
22	import { useFeature } from "@/hooks/useAuthStore";
23	import {
24	  Tooltip,
25	  TooltipContent,
26	  TooltipTrigger,
27	} from "@/components/ui/tooltip";
28	import {
29	  Check,
30	  Pencil,
31	  Plus,
32	  Tag,
33	  Trash2,
34	  UserRoundSearch,
35	  X,
36	} from "lucide-react";
37	import {
38	  AlertDialog,
39	  AlertDialogAction,
40	  AlertDialogCancel,
41	  AlertDialogContent,
42	  AlertDialogDescription,
43	  AlertDialogFooter,
44	  AlertDialogHeader,
45	  AlertDialogTitle,
46	  AlertDialogTrigger,
47	} from "@/components/ui/alert-dialog";
48	
49	type Props = {
50	  isOpen: boolean;
51	  onClose: () => void;
52	  image: GalleryImage;
53	  initialTagMode?: boolean;
54	};
55	
56	interface FaceRegion {
57	  x: number;
58	  y: number;
59	  w: number;
60	  h: number;
61	}
62	
63	const MIN_REGION_SIZE = 0.02;
64	
65	function hasFaceRegion(
66	  link: GalleryMemberLink,
67	): link is GalleryMemberLink & FaceRegion {
68	  return (
69	    link.x !== null && link.y !== null && link.w !== null && link.h !== null
70	  );
71	}
72	
73	function regionFromPoints(
74	  start: { x: number; y: number },
75	  end: { x: number; y: number },
76	): FaceRegion {
77	  return {
78	    x: Math.min(start.x, end.x),
79	    y: Math.min(start.y, end.y),
80	    w: Math.abs(end.x - start.x),
81	    h: Math.abs(end.y - start.y),
82	  };
83	}
84	
85	export const ImageSheet = ({
86	  isOpen,
87	  onClose,
88	  image,
89	  initialTagMode = false,
90	}: Props) => {
91	  const { t } = useTranslation(undefined, {
92	    keyPrefix: "gallery-view.image-sheet",
93	  });
94	  const { members } = useMemberStore();
95	  const {
96	    galleryImages,
97	    updateGalleryImage,
98	    deleteGalleryImage,
99	    addUnknownFace,
100	    updateUnknownFace,
101	    resolveUnknownFace,
102	    removeUnknownFace,
103	  } = useGalleryStore();
104	  // Unknown-face operations persist immediately (unlike member links, which
105	  // batch into formData until Save), so they must read the live store state
106	  // rather than the possibly-stale `image` prop snapshot a caller may be
107	  // holding onto for the sheet's lifetime.
108	  const unknownFaces =
109	    galleryImages.find((candidate) => candidate.id === image.id)
110	      ?.unknownFaces ?? image.unknownFaces;
111	  const treeRole = useTreeStore((state) => state.selectedTree?.role);
112	  const canWrite = treeRole !== "viewer";
113	  const researchTasksEnabled = useFeature("research_tasks");
114	  const [formData, setFormData] = useState<Partial<GalleryImage>>(image);
115	  const [tagMode, setTagMode] = useState(false);
116	  const [draftRegion, setDraftRegion] = useState<FaceRegion | null>(null);
117	  const [draftMemberId, setDraftMemberId] = useState<string | null>(null);
118	  const [newMemberId, setNewMemberId] = useState<string | null>(null);
119	  const [editingMemberId, setEditingMemberId] = useState<string | null>(null);
120	  const [editingFaceId, setEditingFaceId] = useState<string | null>(null);
121	  const [hoveredMemberId, setHoveredMemberId] = useState<string | null>(null);
122	  const [hoveredFaceId, setHoveredFaceId] = useState<string | null>(null);
123	  const [resolvingFaceId, setResolvingFaceId] = useState<string | null>(null);
124	  const [resolveMemberId, setResolveMemberId] = useState<string | null>(null);
125	  const drawingStart = useRef<{ x: number; y: number } | null>(null);
126	
127	  useEffect(() => {
128	    setFormData(image);
129	    setTagMode(initialTagMode);
130	    setDraftRegion(null);
131	    setDraftMemberId(null);
132	    setNewMemberId(null);
133	    setEditingMemberId(null);
134	    setEditingFaceId(null);
135	    setHoveredMemberId(null);
136	    setHoveredFaceId(null);
137	    setResolvingFaceId(null);
138	    setResolveMemberId(null);
139	  }, [image, initialTagMode]);
140	
141	  const memberLinks = formData.memberLinks ?? image.memberLinks;
142	  const editingTag = memberLinks.find(
143	    (link) => link.memberId === editingMemberId && hasFaceRegion(link),
144	  );
145	  const unlinkedMembers = useMemo(
146	    () =>
147	      members.filter(
148	        (member) => !memberLinks.some((link) => link.memberId === member.id),
149	      ),
150	    [memberLinks, members],
151	  );
152	
153	  const memberName = (memberId: string) => {
154	    const member = members.find((candidate) => candidate.id === memberId);
155	    return member ? getMemberFullName(member) : t("unknown-member");
156	  };
157	
158	  const setMemberLinks = (nextLinks: GalleryMemberLink[]) => {
159	    setFormData((current) => ({
160	      ...current,
161	      memberLinks: nextLinks,
162	      linkedMemberIds: nextLinks.map((link) => link.memberId),
163	    }));
164	  };
165	
166	  const handleSave = () => {
167	    updateGalleryImage(image.id, formData)
168	      .then(() => {
169	        toast.success(t("toast-success"));
170	        onClose();
171	      })
172	      .catch(() => toast.error(t("toast-error")));
173	  };
174	
175	  const handleDelete = () => {
176	    deleteGalleryImage(image.id)
177	      .then(() => {
178	        toast.success(t("toast-delete-success"));
179	        onClose();
180	      })
181	      .catch(() => toast.error(t("toast-delete-error")));
182	  };
183	
184	  const updatePoint = (event: PointerEvent<HTMLDivElement>) => {
185	    const bounds = event.currentTarget.getBoundingClientRect();
186	    return {
187	      x: Math.min(1, Math.max(0, (event.clientX - bounds.left) / bounds.width)),
188	      y: Math.min(1, Math.max(0, (event.clientY - bounds.top) / bounds.height)),
189	    };
190	  };
191	
192	  const handleTagPointerDown = (event: PointerEvent<HTMLDivElement>) => {
193	    if (!tagMode || !canWrite || event.button !== 0) return;
194	    const point = updatePoint(event);
195	    drawingStart.current = point;
196	    event.currentTarget.setPointerCapture(event.pointerId);
197	    setDraftRegion({ x: point.x, y: point.y, w: 0, h: 0 });
198	  };
199	
200	  const handleTagPointerMove = (event: PointerEvent<HTMLDivElement>) => {
201	    if (!drawingStart.current) return;
202	    event.preventDefault();
203	    setDraftRegion(regionFromPoints(drawingStart.current, updatePoint(event)));
204	  };
205	
206	  const handleTagPointerUp = (event: PointerEvent<HTMLDivElement>) => {
207	    const start = drawingStart.current;
208	    if (!start) return;
209	    const region = regionFromPoints(start, updatePoint(event));
210	    drawingStart.current = null;
211	    event.currentTarget.releasePointerCapture(event.pointerId);
212	
213	    if (region.w < MIN_REGION_SIZE || region.h < MIN_REGION_SIZE) {
214	      setDraftRegion(null);
215	      return;
216	    }
217	
218	    if (editingFaceId) {
219	      const faceId = editingFaceId;
220	      updateUnknownFace(faceId, region).catch(() =>
221	        toast.error(t("unknown-face-update-error")),
222	      );
223	      setEditingFaceId(null);
224	      setDraftRegion(null);
225	      return;
226	    }
227	
228	    if (editingTag) {
229	      setMemberLinks(
230	        memberLinks.map((link) =>
231	          link.memberId === editingTag.memberId ? { ...link, ...region } : link,
232	        ),
233	      );
234	      setEditingMemberId(null);
235	      setDraftRegion(null);
236	      return;
237	    }
238	
239	    setDraftRegion(region);
240	    setDraftMemberId(null);
241	  };
242	
243	  const handleAddFaceTag = () => {
244	    if (!draftRegion || !draftMemberId) return;
245	    setMemberLinks([
246	      ...memberLinks.filter((link) => link.memberId !== draftMemberId),
247	      { memberId: draftMemberId, ...draftRegion },
248	    ]);
249	    setHoveredMemberId(draftMemberId);
250	    setDraftRegion(null);
251	    setDraftMemberId(null);
252	  };
253	
254	  const handleAddWholeImageLink = () => {
255	    if (!newMemberId) {
256	      return;
257	    }
258	    if (memberLinks.some((link) => link.memberId === newMemberId)) {
259	      toast.info(
260	        t("toast-member-already-linked", { name: memberName(newMemberId) }),
261	      );
262	      return;
263	    }
264	    setMemberLinks([
265	      ...memberLinks,
266	      { memberId: newMemberId, x: null, y: null, w: null, h: null },
267	    ]);
268	    setNewMemberId(null);
269	  };
270	
271	  const handleEditTag = (memberId: string) => {
272	    setTagMode(true);
273	    setEditingMemberId(memberId);
274	    setDraftRegion(null);
275	    setDraftMemberId(null);
276	  };
277	
278	  const handleReassignTag = (memberId: string | null) => {
279	    if (!memberId || !editingTag) return;
280	    setMemberLinks([
281	      ...memberLinks.filter(
282	        (link) =>
283	          link.memberId !== editingTag.memberId && link.memberId !== memberId,
284	      ),
285	      { ...editingTag, memberId },
286	    ]);
287	    setEditingMemberId(memberId);
288	  };
289	
290	  const handleRemoveLink = (memberId: string) => {
291	    setMemberLinks(memberLinks.filter((link) => link.memberId !== memberId));
