300	        setDraftMemberId(null);
301	        setEditingMemberId(null);
302	        setEditingFaceId(null);
303	      }
304	      return !enabled;
305	    });
306	  };
307	
308	  const handleMarkUnknown = () => {
309	    if (!draftRegion) return;
310	    const title = t("unknown-face-task-title", {
311	      // Prefer the possibly-edited (unsaved) title over the prop snapshot so
312	      // the task references what the user currently sees.
