374	    () =>
375	      memberLinks.map((link) => ({ link, name: memberName(link.memberId) })),
376	    [memberLinks, members], // eslint-disable-line react-hooks/exhaustive-deps
377	  );
378	
379	  return (
380	    <Sheet open={isOpen} onOpenChange={onClose}>
381	      <SheetContent className="w-full sm:max-w-[80vw] flex flex-col p-4">
382	        <SheetHeader>
383	          <SheetTitle>{t("title")}</SheetTitle>
384	        </SheetHeader>
385	        <div className="flex-1 grid grid-cols-1 md:grid-cols-2 gap-8 overflow-hidden min-h-0">
386	          <div className="flex items-center justify-center min-h-0 overflow-hidden">
387	            <div className="relative inline-flex max-h-full max-w-full">
388	              <AuthenticatedImage
389	                src={image.imageData}
390	                alt={image.title || t("image-alt")}
