402	              >
403	                {memberLinks.filter(hasFaceRegion).map((link) => {
404	                  const isHighlighted =
405	                    hoveredMemberId === link.memberId ||
406	                    editingMemberId === link.memberId;
407	                  return (
408	                    <Tooltip key={link.memberId}>
409	                      <TooltipTrigger asChild>
