753	                              placeholder={t("face-tags-member-placeholder")}
754	                              noResultsText={t("members-no-results")}
755	                              size="default"
756	                            />
757	                          </div>
758	                          <Button
759	                            type="button"
760	                            disabled={!draftMemberId}
761	                            onClick={handleAddFaceTag}
762	                          >
763	                            {t("add-face-tag")}
764	                          </Button>
765	                        </div>
766	                        {researchTasksEnabled && (
