773	                            >
774	                              <UserRoundSearch />
775	                              {t("mark-unknown-person")}
776	                            </Button>
777	                            <p className="text-xs text-muted-foreground">
778	                              {t("unknown-face-persist-hint")}
779	                            </p>
780	                          </>
781	                        )}
782	                      </div>
783	                    )
784	                  )}
785	                </Field>
786	              )}
787	            </FieldGroup>
788	            {canWrite && (
789	              <div className="flex justify-end gap-2 mt-4 shrink-0">
790	                <Button onClick={handleSave}>{t("save")}</Button>
791	                <AlertDialog>
